{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Hydroxysafflor yellow A, a neutral polyhydroxy C-glycoside, reached 1026 ng/g in rat brain, but it lacks the two basic guanidine groups and net positive charge of the query; this positive glycoside result is not transferable to the polycationic aminoglycoside.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C08"],
      "claim": "A-VI, a triterpenoid saponin glycoside, showed brain penetration (248.7 ng/g), but its neutral/acidic glycoside structure is distinct from the query's streptidine guanidines; the result does not establish CNS access for the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C16"],
      "claim": "Vidarabine showed 35-66% CSF/plasma penetration in humans via nucleoside transporter-mediated uptake; the query is not a nucleoside and lacks the purine base that drives this transport, so this evidence does not apply.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The query is the polycationic aminoglycoside streptomycin. Although several polar glycosides in the evidence set show brain penetration, they lack the guanidine/aminoglycoside pharmacophore, and aminoglycosides are established to have negligible BBB penetration after systemic administration; therefore the query is predicted to lack meaningful CNS access.",
  "evidence_gaps": [
    "No direct brain or CSF measurements for the query or any aminoglycoside in the evidence set.",
    "All positive evidence comes from neutral or nucleoside glycosides, not polycationic aminoglycosides.",
    "Transfer scores are moderate (~0.66-0.70), limiting confidence in cross-class extrapolation."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

